import json
# Check PR data for reviewers
import os
products_dir = 'DATA/products'

for fname in os.listdir(products_dir):
    if not fname.endswith('.json'):
        continue
    with open(os.path.join(products_dir, fname)) as f:
        data = json.load(f)
    if 'prs' in data and data['prs']:
        for pr in data['prs'][:1]:
            print(f'{fname}:')
            print(f'  PR keys: {list(pr.keys())}')
            print(f'  Sample PR: title={pr.get("title")[:60]}...')
            for k in pr.keys():
                if 'review' in k.lower() or 'approv' in k.lower() or 'comment' in k.lower() or 'feedback' in k.lower():
                    print(f'    Key found: {k}')
            break
